const html = $input.first()?.json?.data || '';
const now = new Date();
const tenders = [];

// Extract each card
const cards = html.match(/<div class="ao-card"[\s\S]*?(?=<div class="ao-card"|<div class="ao-pagination mt-3">)/g) || [];

for (const card of cards) {
  // URL and ID
  const urlMatch = card.match(/href="(https:\/\/www\.appeloffres\.com\/appels-offres\/informatique-materiels-et-logiciels\/([^"]+))"\s*class="btn-detail"/);
  if (!urlMatch) continue;

  const url = urlMatch[1];
  const slug = urlMatch[2];
  const id = slug.split('-')[0];

  // Description
  const descMatch = card.match(/<div class="ao-desc">([\s\S]*?)<\/div>/);
  const description = descMatch ? descMatch[1].trim() : '';

  // Publication date
  const dateMatch = card.match(/bi-calendar3"><\/i>\s*([^<]+)/);
  const rawDate = dateMatch ? dateMatch[1].trim() : '';

  // Deadline
  const deadlineMatch = card.match(/bi-alarm"><\/i>\s*([^<]+)/);
  const deadline = deadlineMatch ? deadlineMatch[1].trim() : '';

  // Country
  const countryMatch = card.match(/flag_(\w+)\.png.*?title="([^"]+)"/);
  const country = countryMatch ? countryMatch[2] : 'Unknown';

  // Reference number
  const refMatch = card.match(/bi-hash"><\/i>\s*([^<]+)/);
  const reference = refMatch ? refMatch[1].trim() : '';

  // Skip reported/postponed tenders
  if (description.toLowerCase().includes('report')) continue;

  // Convert DD/MM/YYYY to ISO YYYY-MM-DD
  let isoPublishedDate = '';
  if (rawDate) {
    const p = rawDate.split('/');
    if (p.length === 3) isoPublishedDate = `${p[2]}-${p[1]}-${p[0]}`;
  }

  // Exclude tenders whose deadline has already passed
  if (deadline) {
    const p = deadline.split(' ')[0].split('/');
    if (p.length === 3) {
      const deadlineDate = new Date(`${p[2]}-${p[1]}-${p[0]}`);
      if (deadlineDate < now) continue; // Expired
    }
  }

  tenders.push({
    json: {
      id: `APPELOFFRES-${id}`,
      source: 'appeloffres.com',
      domain: 'Informatique / Logiciels',
      description: description,
      reference: reference,
      country: country,
      published_date: isoPublishedDate || rawDate,
      deadline: deadline,
      url: url,
      detected_at: now.toISOString(),
      status: 'active'
    }
  });
}

return tenders;

