// Parse Prospect Intelligence Dossier from Groq LLM or generate realistic domain dossier
const input = $input.first()?.json || {};
const prev = $('Process RAG Matrix & Staffing').item.json;

let dossier = {};
try {
  const content = input?.choices?.[0]?.message?.content;
  if (content) {
    dossier = JSON.parse(content);
  }
} catch (e) {
  dossier = {};
}

// Fallback / normalization for clean video demo
if (!dossier.sector || !dossier.strategic_priorities) {
  const desc = (prev.description || '').toLowerCase();
  const buyer = prev.buyer || 'Organisme Public / Client Entreprise';
  let sector = 'Secteur Public & E-Gouvernement';
  let budget = 'Grand Compte Institutionnel (5M+ DT)';

  if (desc.includes('banc') || desc.includes('financ')) {
    sector = 'Banque & Services Financiers';
    budget = 'Tier-1 Institution Financière (10M+ DT)';
  } else if (desc.includes('sant') || desc.includes('hospit')) {
    sector = 'Santé Publique & Technologies Médicales';
    budget = 'Programme National de Modernisation (3M-8M DT)';
  } else if (desc.includes('transport') || desc.includes('logist')) {
    sector = 'Transports & Mobilité Urbaine';
